(function() {
    'use strict';

    // ==========================================
    // 配置
    // ==========================================

    const CONFIG = {
        STORAGE_KEY: 'hidden_messages_data',
        AUTO_SAVE_INTERVAL: 5000,
        DEBUG: true,
    };

    // ==========================================
    // 日志系统
    // ==========================================

    const MSG_HIDER_DEBUG = [];
    const MSG_HIDER_MAX_LOG = 500;

    function log(type, message, data = null) {
        if (!CONFIG.DEBUG && type !== 'ERROR') return;

        const timestamp = new Date().toLocaleTimeString('zh-CN', {
            hour12: false,
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            fractionalSecondDigits: 3,
        });
        MSG_HIDER_DEBUG.push({ timestamp, type, message, data });
        if (MSG_HIDER_DEBUG.length > MSG_HIDER_MAX_LOG) {
            MSG_HIDER_DEBUG.splice(0, MSG_HIDER_DEBUG.length - MSG_HIDER_MAX_LOG);
        }

        const prefix = `[完整隐藏][${type}]`;
        if (type === 'ERROR') console.error(prefix, message, data ?? '');
        else if (type === 'WARN') console.warn(prefix, message, data ?? '');
        else console.log(prefix, message, data ?? '');
    }

    function escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = String(text ?? '');
        return div.innerHTML;
    }

    // ==========================================
    // 文档 / 容器 / 消息节点
    // ==========================================

    const topDoc = window.top.document;
    const topWin = window.top;

    function getWorkingDocument() {
        try {
            const currentCount = topDoc.querySelectorAll('.mes[mesid]').length;
            if (currentCount > 0) return topDoc;
        } catch (e) {}

        try {
            if (window.parent && window.parent.document) {
                const parentCount = window.parent.document.querySelectorAll('.mes[mesid]').length;
                if (parentCount > 0) return window.parent.document;
            }
        } catch (e) {}

        return topDoc;
    }

    function getChatContainer(doc) {
        const candidates = [
            '#dialogue',
            '.chat-container',
            '#chat_story_container',
            '.list-messages',
            '.chatdisplay',
            '#chat',
            '#chat_messages',
            '#chat_container',
            '.chat',
            '.simplebar-content-wrapper',
        ];

        for (const sel of candidates) {
            const el = doc.querySelector(sel);
            if (el) return el;
        }

        const firstMsg = doc.querySelector('.mes[mesid]');
        if (!firstMsg) return null;

        let p = firstMsg.parentElement;
        while (p) {
            const style = doc.defaultView.getComputedStyle(p);
            const overflowY = style.overflowY;
            const canScroll = (overflowY === 'auto' || overflowY === 'scroll') && p.scrollHeight > p.clientHeight;
            if (canScroll) return p;
            p = p.parentElement;
        }

        return doc.querySelector('#dialogue') || doc.body;
    }

    function getAllMessages(doc) {
        return Array.from(doc.querySelectorAll('.mes[mesid]'));
    }

    function getMessageText(el) {
        if (!el) return '';
        const textNode =
            el.querySelector('.mes_text') ||
            el.querySelector('.mes_block') ||
            el.querySelector('.message_text') ||
            el;
        return (textNode.innerText || textNode.textContent || '').trim();
    }

    function getMessageId(el) {
        const n = Number(el?.getAttribute?.('mesid'));
        return Number.isFinite(n) ? n : -1;
    }

    function getMessageAuthor(el) {
        const authorEl = el.querySelector('.mes_author');
        if (authorEl) return authorEl.textContent.trim();

        const isUserAttr = el.getAttribute('is_user');
        if (isUserAttr === 'true') return 'User';
        if (isUserAttr === 'false') return 'Assistant';

        return el.getAttribute('data-author') || 'Unknown';
    }

    function isElementVisibleInContainer(el, container, doc) {
        const rect = el.getBoundingClientRect();

        if (!container || container === doc.body || container === doc.documentElement) {
            const vh = (doc.defaultView || window).innerHeight;
            return rect.bottom > 0 && rect.top < vh;
        }

        const crect = container.getBoundingClientRect();
        return rect.bottom > crect.top && rect.top < crect.bottom;
    }

    function getDistanceToContainerTop(el, container, doc) {
        const rect = el.getBoundingClientRect();

        if (!container || container === doc.body || container === doc.documentElement) {
            return Math.abs(rect.top);
        }

        const crect = container.getBoundingClientRect();
        return Math.abs(rect.top - crect.top);
    }

    function getCurrentVisibleMessage() {
        const doc = getWorkingDocument();
        const container = getChatContainer(doc);
        const list = getAllMessages(doc);

        if (!list.length) {
            log('ERROR', '没有找到 .mes[mesid] 节点');
            return { doc, container, el: null };
        }

        let best = null;
        let bestScore = Infinity;

        for (const el of list) {
            const visible = isElementVisibleInContainer(el, container, doc);
            const score = getDistanceToContainerTop(el, container, doc);

            if (visible && score < bestScore) {
                best = el;
                bestScore = score;
            }
        }

        if (!best) {
            log('WARN', '没有找到容器视口内的消息');
            return { doc, container, el: null };
        }

        return { doc, container, el: best };
    }

    // ==========================================
    // 隐藏核心功能
    // ==========================================

    // 隐藏消息存储
    let hiddenMessages = new Map(); // key: mesid, value: { element, messageData, hideTime }
    let hiddenIdsSet = new Set(); // 快速查询
    let hideHistory = []; // 隐藏历史记录，用于"显示最近隐藏"

    // 保存到localStorage
    function saveHiddenMessages() {
        try {
            const dataToSave = {
                hiddenIds: Array.from(hiddenIdsSet),
                lastUpdate: Date.now(),
                version: '2.0',
            };
            localStorage.setItem(CONFIG.STORAGE_KEY, JSON.stringify(dataToSave));
            log('INFO', '隐藏消息列表已保存', { count: hiddenIdsSet.size });
        } catch (e) {
            log('ERROR', '保存隐藏消息失败', e.message);
        }
    }

    // 加载隐藏消息
    function loadHiddenMessages() {
        try {
            const saved = localStorage.getItem(CONFIG.STORAGE_KEY);
            if (saved) {
                const data = JSON.parse(saved);
                if (data.hiddenIds && Array.isArray(data.hiddenIds)) {
                    hiddenIdsSet = new Set(data.hiddenIds);
                    log('INFO', '已加载隐藏消息列表', { count: hiddenIdsSet.size });
                    return true;
                }
            }
        } catch (e) {
            log('ERROR', '加载隐藏消息失败', e.message);
        }
        return false;
    }

    // 深度隐藏消息
    function deepHideMessage(messageElement, messageId, options = {}) {
        if (!messageElement) return false;

        const id = String(messageId);

        if (hiddenIdsSet.has(id)) {
            log('WARN', `消息 #${id} 已经被隐藏了`);
            return false;
        }

        const messageData = {
            id: messageId,
            text: getMessageText(messageElement).slice(0, 500),
            author: getMessageAuthor(messageElement),
            timestamp: Date.now(),
            originalDisplay: messageElement.style.display,
        };

        hiddenIdsSet.add(id);
        hiddenMessages.set(id, {
            element: messageElement,
            messageData: messageData,
            hideTime: Date.now(),
        });

        // 添加到历史记录（用于显示最近隐藏）
        hideHistory.unshift({ id, time: Date.now() });
        if (hideHistory.length > 100) hideHistory.pop();

        messageElement.classList.add('deep-hidden-message');

        if (options.animate !== false) {
            messageElement.classList.add('hiding-animation');
            setTimeout(() => {
                messageElement.style.display = 'none';
                messageElement.classList.remove('hiding-animation');
            }, 200);
        } else {
            messageElement.style.display = 'none';
        }

        log('ACTION', `深度隐藏消息 #${id}`, {
            author: messageData.author,
            text: messageData.text.slice(0, 100),
        });

        saveHiddenMessages();
        return true;
    }

    // 显示消息
    function showMessage(messageId) {
        const id = String(messageId);
        const record = hiddenMessages.get(id);

        if (!record || !record.element) {
            log('WARN', `未找到隐藏的消息 #${id}`);
            return false;
        }

        record.element.style.display = record.messageData.originalDisplay || '';
        record.element.classList.remove('deep-hidden-message');

        hiddenIdsSet.delete(id);
        hiddenMessages.delete(id);

        // 从历史中移除
        hideHistory = hideHistory.filter(h => h.id !== id);

        saveHiddenMessages();

        log('ACTION', `显示消息 #${id}`);
        return true;
    }

    // 显示所有隐藏的消息
    function showAllHiddenMessages() {
        if (hiddenIdsSet.size === 0) {
            if (typeof toastr !== 'undefined') toastr.info('没有隐藏的消息');
            return 0;
        }

        let restoredCount = 0;

        for (const [id, record] of hiddenMessages) {
            if (record.element) {
                record.element.style.display = record.messageData.originalDisplay || '';
                record.element.classList.remove('deep-hidden-message');
                restoredCount++;
            }
        }

        hiddenIdsSet.clear();
        hiddenMessages.clear();
        hideHistory = [];
        saveHiddenMessages();

        log('ACTION', `显示所有隐藏的消息`, { restoredCount });

        if (typeof toastr !== 'undefined') {
            toastr.success(`已显示 ${restoredCount} 条隐藏的消息`);
        }

        return restoredCount;
    }

    // 显示最近隐藏的一条消息
    function showLastHiddenMessage() {
        if (hideHistory.length === 0) {
            if (typeof toastr !== 'undefined') toastr.info('没有隐藏的消息');
            return false;
        }

        const lastHidden = hideHistory[0];
        const success = showMessage(lastHidden.id);

        if (success && typeof toastr !== 'undefined') {
            toastr.success(`已显示消息 #${lastHidden.id}`);

            // 滚动到显示的消息
            const record = hiddenMessages.get(lastHidden.id);
            if (record && record.element) {
                setTimeout(() => {
                    record.element.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }, 100);
            }
        }

        return success;
    }

    // 查找下一个可见消息
    function findNextVisibleMessage(currentEl, doc) {
        const allMessages = getAllMessages(doc);
        const currentIndex = allMessages.findIndex(msg => msg === currentEl);

        for (let i = currentIndex + 1; i < allMessages.length; i++) {
            const msg = allMessages[i];
            const msgId = getMessageId(msg);
            if (!hiddenIdsSet.has(String(msgId)) && msg.offsetParent !== null) {
                return msg;
            }
        }

        return null;
    }

    // 查找上一个可见消息
    function findPrevVisibleMessage(currentEl, doc) {
        const allMessages = getAllMessages(doc);
        const currentIndex = allMessages.findIndex(msg => msg === currentEl);

        for (let i = currentIndex - 1; i >= 0; i--) {
            const msg = allMessages[i];
            const msgId = getMessageId(msg);
            if (!hiddenIdsSet.has(String(msgId)) && msg.offsetParent !== null) {
                return msg;
            }
        }

        return null;
    }

    // ==========================================
    // 用户功能函数
    // ==========================================

    // 1. 隐藏当前消息并自动滚动到下一个可见消息
    function hideCurrentAndScrollNext() {
        const { doc, container, el: currentEl } = getCurrentVisibleMessage();

        if (!currentEl) {
            if (typeof toastr !== 'undefined') toastr.error('未找到当前消息');
            return false;
        }

        const messageId = getMessageId(currentEl);
        const success = deepHideMessage(currentEl, messageId);

        if (success && typeof toastr !== 'undefined') {
            toastr.success(`已隐藏消息 #${messageId}`);

            // 自动滚动到下一个可见消息
            setTimeout(() => {
                const nextVisible = findNextVisibleMessage(currentEl, doc);
                if (nextVisible) {
                    nextVisible.scrollIntoView({ behavior: 'smooth', block: 'start' });
                } else {
                    const prevVisible = findPrevVisibleMessage(currentEl, doc);
                    if (prevVisible) {
                        prevVisible.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    }
                }
            }, 250);
        } else if (!success && typeof toastr !== 'undefined') {
            toastr.warning(`消息 #${messageId} 已经被隐藏`);
        }

        return success;
    }

    // 2. 切换当前消息的隐藏/显示状态
    function toggleHideCurrentMessage() {
        const { doc, container, el: currentEl } = getCurrentVisibleMessage();

        if (!currentEl) {
            if (typeof toastr !== 'undefined') toastr.error('未找到当前消息');
            return false;
        }

        const messageId = getMessageId(currentEl);
        const id = String(messageId);

        if (hiddenIdsSet.has(id)) {
            // 已隐藏，则显示
            const success = showMessage(id);
            if (success && typeof toastr !== 'undefined') {
                toastr.success(`已显示消息 #${messageId}`);
                currentEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
            return success;
        } else {
            // 未隐藏，则隐藏
            const success = deepHideMessage(currentEl, messageId);
            if (success && typeof toastr !== 'undefined') {
                toastr.success(`已隐藏消息 #${messageId}`);

                // 自动滚动到下一个可见消息
                setTimeout(() => {
                    const nextVisible = findNextVisibleMessage(currentEl, doc);
                    if (nextVisible) {
                        nextVisible.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    }
                }, 250);
            }
            return success;
        }
    }

    // 3. 隐藏上下文消息（当前及之前的所有消息）
    function hideContextMessages() {
        const { doc, container, el: currentEl } = getCurrentVisibleMessage();

        if (!currentEl) {
            if (typeof toastr !== 'undefined') toastr.error('未找到当前消息');
            return 0;
        }

        const currentId = getMessageId(currentEl);
        const allMessages = getAllMessages(doc);

        let hiddenCount = 0;
        const toHide = [];

        // 收集所有ID小于等于当前消息的消息
        for (const msg of allMessages) {
            const msgId = getMessageId(msg);
            if (msgId <= currentId && !hiddenIdsSet.has(String(msgId))) {
                toHide.push({ element: msg, id: msgId });
            }
        }

        // 执行隐藏（从旧到新）
        for (const { element, id } of toHide) {
            if (deepHideMessage(element, id, { animate: false })) {
                hiddenCount++;
            }
        }

        log('ACTION', `隐藏上下文消息`, { currentId, hiddenCount });

        if (typeof toastr !== 'undefined') {
            toastr.success(`已隐藏 ${hiddenCount} 条上下文消息（包含当前消息）`);
        }

        // 刷新视图，滚动到第一个可见消息
        setTimeout(() => {
            const remainingMsg = findNextVisibleMessage(currentEl, doc);
            if (remainingMsg) {
                remainingMsg.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
        }, 300);

        return hiddenCount;
    }

    // 4. 隐藏后续消息（当前及之后的所有消息）
    function hideFollowingMessages() {
        const { doc, container, el: currentEl } = getCurrentVisibleMessage();

        if (!currentEl) {
            if (typeof toastr !== 'undefined') toastr.error('未找到当前消息');
            return 0;
        }

        const currentId = getMessageId(currentEl);
        const allMessages = getAllMessages(doc);

        let hiddenCount = 0;
        const toHide = [];

        // 收集所有ID大于等于当前消息的消息
        for (const msg of allMessages) {
            const msgId = getMessageId(msg);
            if (msgId >= currentId && !hiddenIdsSet.has(String(msgId))) {
                toHide.push({ element: msg, id: msgId });
            }
        }

        // 执行隐藏
        for (const { element, id } of toHide) {
            if (deepHideMessage(element, id, { animate: false })) {
                hiddenCount++;
            }
        }

        log('ACTION', `隐藏后续消息`, { currentId, hiddenCount });

        if (typeof toastr !== 'undefined') {
            toastr.success(`已隐藏 ${hiddenCount} 条后续消息（包含当前消息）`);
        }

        // 刷新视图
        setTimeout(() => {
            const remainingMsg = findPrevVisibleMessage(currentEl, doc);
            if (remainingMsg) {
                remainingMsg.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
        }, 300);

        return hiddenCount;
    }

    // ==========================================
    // 拦截消息生成（深度隐藏核心功能）
    // ==========================================

    let originalGetChatMessages = null;
    let originalGetMessages = null;

    function filterHiddenMessages(messages) {
        if (!messages || !Array.isArray(messages)) return messages;

        const filtered = messages.filter(msg => {
            const msgId = msg?.mesId || msg?.id;
            if (msgId === undefined) return true;
            return !hiddenIdsSet.has(String(msgId));
        });

        if (filtered.length !== messages.length) {
            log('INFO', `过滤消息: 原始 ${messages.length} 条, 过滤后 ${filtered.length} 条`);
        }

        return filtered;
    }

    function setupMessageGenerationInterceptor() {
        // 拦截 getChatMessages
        if (typeof window.getChatMessages === 'function' && !window.__hiddenMsgWrapped) {
            originalGetChatMessages = window.getChatMessages;
            window.getChatMessages = function(...args) {
                const result = originalGetChatMessages.apply(this, args);
                return filterHiddenMessages(result);
            };
            log('INFO', '已拦截 getChatMessages 函数');
        }

        // 拦截 getMessages
        if (typeof window.getMessages === 'function' && !window.__getMessagesWrapped) {
            originalGetMessages = window.getMessages;
            window.getMessages = function(...args) {
                const result = originalGetMessages.apply(this, args);
                return filterHiddenMessages(result);
            };
            log('INFO', '已拦截 getMessages 函数');
        }

        window.__hiddenMsgWrapped = true;

        // 监听 DOM 变化
        const observer = new MutationObserver((mutations) => {
            for (const mutation of mutations) {
                for (const node of mutation.addedNodes) {
                    if (node.nodeType === 1 && node.matches && node.matches('.mes[mesid]')) {
                        const msgId = getMessageId(node);
                        if (hiddenIdsSet.has(String(msgId))) {
                            node.style.display = 'none';
                            node.classList.add('deep-hidden-message');
                        }
                    }
                }
            }
        });

        const doc = getWorkingDocument();
        observer.observe(doc.body, {
            childList: true,
            subtree: true,
        });

        log('INFO', '消息生成拦截器已设置');
    }

    // 清理过期的隐藏记录
    function cleanupExpiredHiddenMessages() {
        const doc = getWorkingDocument();
        const existingMessages = getAllMessages(doc);
        const existingIds = new Set(existingMessages.map(msg => getMessageId(msg)));

        let removedCount = 0;
        for (const id of hiddenIdsSet) {
            if (!existingIds.has(Number(id))) {
                hiddenIdsSet.delete(id);
                hiddenMessages.delete(String(id));
                hideHistory = hideHistory.filter(h => h.id !== id);
                removedCount++;
            }
        }

        if (removedCount > 0) {
            log('INFO', `清理了 ${removedCount} 条过期的隐藏记录`);
            saveHiddenMessages();
        }
    }

    // 获取隐藏消息统计
    function getHiddenStats() {
        return {
            count: hiddenIdsSet.size,
            messages: Array.from(hiddenMessages.values()).map(record => ({
                id: record.messageData.id,
                text: record.messageData.text,
                author: record.messageData.author,
                hideTime: record.hideTime,
            })).sort((a, b) => a.id - b.id),
            history: hideHistory,
        };
    }

    // 导出隐藏列表
    function exportHiddenList() {
        const stats = getHiddenStats();
        const exportData = {
            exportTime: new Date().toISOString(),
            count: stats.count,
            messages: stats.messages,
            version: '2.0',
        };

        const dataStr = JSON.stringify(exportData, null, 2);
        const blob = new Blob([dataStr], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `hidden_messages_${Date.now()}.json`;
        a.click();
        URL.revokeObjectURL(url);

        if (typeof toastr !== 'undefined') {
            toastr.success(`已导出 ${stats.count} 条隐藏消息记录`);
        }
    }

    // 导入隐藏列表
    function importHiddenList(file) {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = JSON.parse(e.target.result);
                if (data.messages && Array.isArray(data.messages)) {
                    data.messages.forEach(msg => hiddenIdsSet.add(String(msg.id)));
                    saveHiddenMessages();

                    if (typeof toastr !== 'undefined') {
                        toastr.success(`已导入 ${data.messages.length} 条隐藏记录，刷新页面后生效`);
                    }

                    setTimeout(() => location.reload(), 1500);
                } else if (data.hiddenIds && Array.isArray(data.hiddenIds)) {
                    data.hiddenIds.forEach(id => hiddenIdsSet.add(String(id)));
                    saveHiddenMessages();

                    if (typeof toastr !== 'undefined') {
                        toastr.success(`已导入 ${data.hiddenIds.length} 条隐藏记录，刷新页面后生效`);
                    }

                    setTimeout(() => location.reload(), 1500);
                }
            } catch (err) {
                log('ERROR', '导入失败', err.message);
                if (typeof toastr !== 'undefined') {
                    toastr.error('导入失败，文件格式错误');
                }
            }
        };
        reader.readAsText(file);
    }

    // ==========================================
    // 调试窗口
    // ==========================================

    async function openDebugConsole() {
        function renderLogs() {
            if (MSG_HIDER_DEBUG.length === 0) {
                return '<div style="text-align:center;color:#666;padding:40px;">暂无日志</div>';
            }
            return MSG_HIDER_DEBUG.map(entry => {
                const colorMap = {
                    INFO: '#90caf9',
                    ACTION: '#ce93d8',
                    WARN: '#fff176',
                    ERROR: '#e57373',
                };
                const color = colorMap[entry.type] || '#ccc';
                const dataStr = entry.data !== null && entry.data !== undefined
                    ? `<div style="color:#999;margin-top:4px;white-space:pre-wrap;word-break:break-all;">${escapeHtml(
                        typeof entry.data === 'object' ? JSON.stringify(entry.data, null, 2) : String(entry.data)
                    )}</div>`
                    : '';
                return `
                <div style="padding:6px 8px;border-bottom:1px solid #333;font-family:monospace;font-size:12px;line-height:1.5;">
                    <span style="color:#666;">${entry.timestamp}</span>
                    <span style="color:${color};font-weight:bold;margin-left:8px;">[${entry.type}]</span>
                    <span style="color:#ddd;margin-left:8px;">${escapeHtml(entry.message)}</span>
                    ${dataStr}
                </div>`;
            }).join('');
        }

        const stats = getHiddenStats();
        const hiddenListHtml = stats.count > 0 
            ? `<div style="margin-top:8px;padding:8px;background:#1a1a1a;border-radius:4px;max-height:200px;overflow-y:auto;">
                <div style="color:#ffb74d;font-weight:bold;">隐藏的消息列表 (${stats.count}条):</div>
                ${stats.messages.map(m => 
                    `<div style="margin-top:4px;padding:4px;border-left:2px solid #ffb74d;background:#252525;">
                        <span style="color:#90caf9;">#${m.id}</span>
                        <span style="color:#81c784;margin-left:8px;">[${m.author}]</span>
                        <span style="color:#ccc;margin-left:8px;">${escapeHtml(m.text.slice(0, 80))}${m.text.length > 80 ? '...' : ''}</span>
                        <span style="color:#666;margin-left:8px;font-size:11px;">${new Date(m.hideTime).toLocaleTimeString()}</span>
                    </div>`
                ).join('')}
            </div>`
            : '<div style="color:#666;margin-top:8px;">暂无隐藏的消息</div>';

        const html = `
        <div style="padding:8px;display:flex;flex-direction:column;height:70vh;">
            <div style="font-size:16px;font-weight:bold;margin-bottom:8px;text-align:center;">
                🚫 完整消息隐藏助手 - 调试窗口
            </div>
            <div style="font-size:12px;color:#aaa;line-height:1.8;margin-bottom:8px;background:#1a1a1a;padding:8px;border-radius:4px;">
                <div>📊 统计信息</div>
                <div>├─ 已隐藏消息数: ${stats.count}</div>
                <div>└─ 存储状态: ${localStorage.getItem(CONFIG.STORAGE_KEY) ? '已保存' : '无数据'}</div>
                <div style="margin-top:4px;color:#81c784;">💡 提示: 隐藏的消息在下次生成时不会被读取到上下文中</div>
            </div>
            ${hiddenListHtml}
            <div style="margin-bottom:8px;margin-top:12px;display:flex;gap:6px;flex-wrap:wrap;">
                <button id="mh_hide_current" style="padding:4px 10px;background:#4caf50;">🙈 隐藏当前并滚动</button>
                <button id="mh_toggle" style="padding:4px 10px;background:#2196f3;">🔄 切换隐藏状态</button>
                <button id="mh_show_last" style="padding:4px 10px;background:#ff9800;">👁️ 显示最近隐藏</button>
                <button id="mh_show_all" style="padding:4px 10px;background:#2196f3;">👁️‍🗨️ 显示全部</button>
                <button id="mh_hide_context" style="padding:4px 10px;background:#ff9800;">📚 隐藏上下文</button>
                <button id="mh_hide_following" style="padding:4px 10px;background:#ff9800;">⏩ 隐藏后续</button>
                <button id="mh_export" style="padding:4px 10px;">📤 导出列表</button>
                <button id="mh_import" style="padding:4px 10px;">📥 导入列表</button>
                <button id="mh_cleanup" style="padding:4px 10px;">🧹 清理过期</button>
                <button id="mh_clear_log" style="padding:4px 10px;">🗑️ 清空日志</button>
            </div>
            <div id="mh_log_container" style="
                flex:1;
                overflow-y:auto;
                background:#111;
                border:1px solid #444;
                border-radius:4px;
                font-family:monospace;
                font-size:11px;
            ">${renderLogs()}</div>
        </div>`;

        const popup = new SillyTavern.Popup(
            html,
            SillyTavern.POPUP_TYPE.TEXT,
            '',
            {
                wide: true,
                large: true,
                okButton: '关闭',
                onOpen: async (popup) => {
                    const dlg = popup.dlg;
                    const containerEl = dlg.querySelector('#mh_log_container');
                    const importInput = document.createElement('input');
                    importInput.type = 'file';
                    importInput.accept = '.json';
                    importInput.style.display = 'none';
                    dlg.appendChild(importInput);

                    function refresh() {
                        containerEl.innerHTML = renderLogs();
                        containerEl.scrollTop = containerEl.scrollHeight;
                    }

                    dlg.querySelector('#mh_hide_current')?.addEventListener('click', () => {
                        hideCurrentAndScrollNext();
                        refresh();
                    });

                    dlg.querySelector('#mh_toggle')?.addEventListener('click', () => {
                        toggleHideCurrentMessage();
                        refresh();
                    });

                    dlg.querySelector('#mh_show_last')?.addEventListener('click', () => {
                        showLastHiddenMessage();
                        refresh();
                    });

                    dlg.querySelector('#mh_show_all')?.addEventListener('click', () => {
                        showAllHiddenMessages();
                        refresh();
                    });

                    dlg.querySelector('#mh_hide_context')?.addEventListener('click', () => {
                        hideContextMessages();
                        refresh();
                    });

                    dlg.querySelector('#mh_hide_following')?.addEventListener('click', () => {
                        hideFollowingMessages();
                        refresh();
                    });

                    dlg.querySelector('#mh_export')?.addEventListener('click', () => {
                        exportHiddenList();
                    });

                    dlg.querySelector('#mh_import')?.addEventListener('click', () => {
                        importInput.click();
                    });

                    importInput.addEventListener('change', (e) => {
                        if (e.target.files.length > 0) {
                            importHiddenList(e.target.files[0]);
                        }
                        importInput.value = '';
                    });

                    dlg.querySelector('#mh_cleanup')?.addEventListener('click', () => {
                        cleanupExpiredHiddenMessages();
                        refresh();
                        if (typeof toastr !== 'undefined') {
                            toastr.success('已清理过期的隐藏记录');
                        }
                    });

                    dlg.querySelector('#mh_clear_log')?.addEventListener('click', () => {
                        MSG_HIDER_DEBUG.length = 0;
                        log('INFO', '日志已清空');
                        refresh();
                    });

                    refresh();
                },
            }
        );

        await popup.show();
    }

    // ==========================================
    // 添加全局样式
    // ==========================================

    function addGlobalStyles() {
        const styleId = 'complete-message-hider-styles';
        if (topDoc.getElementById(styleId)) return;

        const style = topDoc.createElement('style');
        style.id = styleId;
        style.textContent = `
            .deep-hidden-message {
                display: none !important;
            }

            @keyframes hideFadeOut {
                from {
                    opacity: 1;
                    transform: scale(1);
                    max-height: 500px;
                    margin: 8px 0;
                    padding: 12px;
                }
                to {
                    opacity: 0;
                    transform: scale(0.95);
                    max-height: 0;
                    margin: 0;
                    padding: 0;
                }
            }

            .hiding-animation {
                animation: hideFadeOut 0.2s ease-out forwards;
                overflow: hidden;
            }
        `;
        topDoc.head.appendChild(style);
    }

    // ==========================================
    // 按钮注册
    // ==========================================

    function registerButtons() {
        const buttons = [
            { name: '🙈 隐藏并滚动', visible: true },
            { name: '🔄 切换隐藏', visible: true },
            { name: '👁️ 显示最近', visible: true },
            { name: '👁️‍🗨️ 显示全部', visible: true },
            { name: '📚 隐藏上下文', visible: true },
            { name: '⏩ 隐藏后续', visible: true },
            { name: '🔧 调试', visible: true },
        ];

        if (typeof replaceScriptButtons === 'function') {
            replaceScriptButtons(buttons);

            if (typeof eventOn === 'function') {
                eventOn(getButtonEvent('🙈 隐藏并滚动'), hideCurrentAndScrollNext);
                eventOn(getButtonEvent('🔄 切换隐藏'), toggleHideCurrentMessage);
                eventOn(getButtonEvent('👁️ 显示最近'), showLastHiddenMessage);
                eventOn(getButtonEvent('👁️‍🗨️ 显示全部'), showAllHiddenMessages);
                eventOn(getButtonEvent('📚 隐藏上下文'), hideContextMessages);
                eventOn(getButtonEvent('⏩ 隐藏后续'), hideFollowingMessages);
                eventOn(getButtonEvent('🔧 调试'), openDebugConsole);
            }
        } else if (typeof eventOnButton === 'function') {
            eventOnButton("🙈 隐藏并滚动", hideCurrentAndScrollNext);
            eventOnButton("🔄 切换隐藏", toggleHideCurrentMessage);
            eventOnButton("👁️ 显示最近", showLastHiddenMessage);
            eventOnButton("👁️‍🗨️ 显示全部", showAllHiddenMessages);
            eventOnButton("📚 隐藏上下文", hideContextMessages);
            eventOnButton("⏩ 隐藏后续", hideFollowingMessages);
            eventOnButton("🔧 调试", openDebugConsole);
        } else {
            console.error("无法注册按钮: eventOnButton 和 replaceScriptButtons 都不可用");
        }
    }

    // ==========================================
    // 初始化
    // ==========================================

    function init() {
        log('INFO', '完整消息隐藏助手脚本开始加载');

        loadHiddenMessages();
        addGlobalStyles();
        setupMessageGenerationInterceptor();

        setTimeout(() => cleanupExpiredHiddenMessages(), 2000);

        setTimeout(() => {
            const doc = getWorkingDocument();
            const messages = getAllMessages(doc);
            for (const msg of messages) {
                const msgId = getMessageId(msg);
                if (hiddenIdsSet.has(String(msgId))) {
                    msg.style.display = 'none';
                    msg.classList.add('deep-hidden-message');
                }
            }
            log('INFO', `已应用隐藏状态到 ${hiddenIdsSet.size} 条消息`);
        }, 1000);

        log('INFO', '完整消息隐藏助手脚本加载完成');
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => {
            init();
            registerButtons();
        });
    } else {
        init();
        registerButtons();
    }

})();
